def factorial(number):
    if number <= 1:
        return 1
    return number * factorial(number - 1)

def unique_values(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def count_up_to(limit):
    current = 1
    while current <= limit:
        yield current
        current += 1

def char_frequency(text):
    counts = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    return counts

